"use client";

import { motion, useReducedMotion } from "framer-motion";

export function PrimaryButton({ children }: { children: React.ReactNode }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.button
      whileHover={shouldReduceMotion ? undefined : { y: -2 }}
      whileTap={{ scale: 0.96, y: 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
      className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg bg-zinc-900 px-5 py-2.5 text-sm font-medium text-white dark:text-zinc-900 shadow-[0_1px_2px_rgba(24,24,27,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-zinc-800 hover:shadow-[0_12px_24px_-8px_rgba(24,24,27,0.65)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-900 active:bg-zinc-950 dark:bg-zinc-50 dark:shadow-[0_1px_2px_rgba(250,250,250,0.35)] dark:hover:bg-zinc-200 dark:hover:shadow-[0_12px_24px_-8px_rgba(250,250,250,0.55)] dark:focus-visible:outline-zinc-50 dark:active:bg-zinc-300"
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
      />
      <span className="relative">{children}</span>
    </motion.button>
  );
}

export function GhostButton({ children }: { children: React.ReactNode }) {
  return (
    <button className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg border border-zinc-300 px-5 py-2.5 text-sm font-medium text-zinc-700 transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-400 active:scale-[0.97] dark:border-zinc-600 dark:text-zinc-200">
      <span
        aria-hidden
        className="absolute inset-0 origin-left scale-x-0 bg-zinc-900 transition-transform duration-300 ease-out group-hover:scale-x-100 motion-reduce:transition-none dark:bg-white"
      />
      <span className="relative transition-colors duration-300 group-hover:text-white dark:group-hover:text-zinc-900">
        {children}
      </span>
    </button>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function ToggleSwitch({ label }: { label: string }) {
  const [checked, setChecked] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <label className="flex items-center gap-3 cursor-pointer select-none">
      <motion.button
        role="switch"
        aria-checked={checked}
        onClick={() => setChecked((v) => !v)}
        whileTap={{ scale: 0.93 }}
        className={`relative h-6 w-11 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-900 ${
          checked ? "bg-zinc-900" : "bg-zinc-300 dark:bg-zinc-600"
        }`}
      >
        <motion.span
          animate={{ x: checked ? 22 : 2 }}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 700, damping: 32 }
          }
          className="absolute top-0.5 block h-5 w-5 rounded-full bg-white shadow-md"
        />
      </motion.button>
      <span className="text-sm text-zinc-700 dark:text-zinc-200">{label}</span>
    </label>
  );
}

export function TextField({ label }: { label: string }) {
  return (
    <div className="relative w-full">
      <input
        id="text-field"
        type="text"
        placeholder=" "
        className="peer w-full rounded-lg border border-zinc-300 bg-white px-3.5 pb-2 pt-5 text-sm text-zinc-900 outline-none transition-colors focus:border-zinc-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-900 dark:border-zinc-600 dark:bg-neutral-950 dark:text-white"
      />
      <label
        htmlFor="text-field"
        className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-zinc-400 transition-all duration-200 ease-out peer-focus:top-3.5 peer-focus:text-xs peer-focus:text-zinc-900 peer-[:not(:placeholder-shown)]:top-3.5 peer-[:not(:placeholder-shown)]:text-xs peer-[:not(:placeholder-shown)]:text-zinc-500 dark:peer-[:not(:placeholder-shown)]:text-zinc-400"
      >
        {label}
      </label>
      <span className="pointer-events-none absolute inset-x-3.5 bottom-1.5 h-px origin-left scale-x-0 bg-zinc-900 transition-transform duration-300 ease-out peer-focus:scale-x-100" />
    </div>
  );
}

type BadgeTone = "neutral" | "success" | "warning" | "live";

const tones: Record<BadgeTone, string> = {
  neutral: "bg-zinc-100 text-zinc-700 dark:bg-neutral-900 dark:text-zinc-300",
  success: "bg-green-100 text-green-700 dark:bg-green-500/15 dark:text-green-400",
  warning: "bg-zinc-200 text-zinc-900 dark:bg-white/10 dark:text-zinc-100",
  live: "bg-zinc-900 text-zinc-50 dark:bg-zinc-50 dark:text-zinc-900",
};

export function Badge({ tone = "neutral", children }: { tone?: BadgeTone; children: React.ReactNode }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium transition-transform duration-200 ease-out hover:scale-105 ${tones[tone]}`}
    >
      {tone === "live" && (
        <span className="relative flex h-1.5 w-1.5">
          <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-zinc-500 opacity-75 motion-reduce:hidden" />
          <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-zinc-500" />
        </span>
      )}
      {children}
    </span>
  );
}

export function Breadcrumbs({
  items,
}: {
  items: { label: string; href?: string }[];
}) {
  return (
    <nav aria-label="Breadcrumb">
      <ol className="flex items-center gap-2 text-sm">
        {items.map((item, i) => (
          <li key={item.label} className="flex items-center gap-2">
            {item.href ? (
              <a
                href={item.href}
                className="group relative text-zinc-500 transition-colors hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
              >
                {item.label}
                <span className="absolute inset-x-0 -bottom-0.5 h-px origin-left scale-x-0 bg-zinc-900 transition-transform duration-300 ease-out group-hover:scale-x-100 dark:bg-white" />
              </a>
            ) : (
              <span aria-current="page" className="font-medium text-zinc-900 dark:text-white">
                {item.label}
              </span>
            )}
            {i < items.length - 1 && <span className="text-zinc-300 dark:text-zinc-600">/</span>}
          </li>
        ))}
      </ol>
    </nav>
  );
}
